<?php
require_once __DIR__.'/../includes/admin-functions.php';$schema=dental_schema($pdo);$labIdColumn=$schema->labId();$imageIdColumn=$schema->imageId();$imagePathColumn=$schema->imagePath();$hasDocument=$schema->hasDocument();
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Méthode non autorisée.');}csrf_check();$id=(int)($_POST['laboratoire_id']??0);if($id<1){admin_flash('error','Identifiant invalide.');admin_redirect('laboratoires.php');}
try{$document=null;if($hasDocument){$q=$pdo->prepare("SELECT document_verification FROM laboratoire WHERE `$labIdColumn`=?");$q->execute([$id]);$document=$q->fetchColumn();}$q=$pdo->prepare("SELECT `$imagePathColumn` FROM image_laboratoire WHERE laboratoire_id=?");$q->execute([$id]);$photos=$q->fetchAll(PDO::FETCH_COLUMN);$pdo->beginTransaction();$pdo->prepare("DELETE FROM laboratoire WHERE `$labIdColumn`=?")->execute([$id]);$pdo->commit();admin_delete_file($document?:null,'documents');foreach($photos as $photo)admin_delete_file($photo,'laboratoires');admin_flash('success','Laboratoire supprimé.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();admin_flash('error','La suppression du laboratoire a échoué.');}admin_redirect('laboratoires.php');
